import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './index.css'; // or './App.css' if you prefer

function App() {
  // ALL HOOKS MUST BE AT THE TOP — IN THIS ORDER
  const [user, setUser] = useState(null);
  const [page, setPage] = useState('login');
  const [emailInput, setEmailInput] = useState('');
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [formData, setFormData] = useState({});
  const [allStudents, setAllStudents] = useState([]);
  const [selectedCourseStudents, setSelectedCourseStudents] = useState([]);
  const [showStudentsModal, setShowStudentsModal] = useState(false);

  const API = 'http://localhost:5000/api';

  // Helper: Map page name to API endpoint
  const getEndpoint = (pageName) => {
    if (pageName === 'courses') {
      return user?.role === 'instructor' ? `courses?instructorid=${user.id}` : 'courses';
    }
    if (pageName === 'assignments') return 'assignments';
    if (pageName === 'announcements') return 'announcements';
    if (pageName === 'submissions') return 'submissions';
    if (pageName === 'students') return 'users?role=student';
    return null;
  };

  // Empty form based on page
  const getEmptyForm = (pageName) => {
    if (pageName === 'courses') return { title: '', description: '', syllabus: '' };
    if (pageName === 'assignments') return { title: '', duedate: '', description: '' };
    if (pageName === 'announcements') return { title: '', message: '' };
    if (pageName === 'students') return { name: '', email: '' };
    return {};
  };

  // Login
  const login = async (e) => {
    e.preventDefault();
    if (!emailInput.trim()) return alert('Please enter your email');
    try {
      const res = await axios.post(`${API}/users/login`, { email: emailInput.trim() });
      setUser(res.data);
      setPage('dashboard');
    } catch (err) {
      alert('Login failed — user not found');
    }
  };

  // Logout
  const logout = () => {
    setUser(null);
    setPage('login');
    setEmailInput('');
    setShowForm(false);
    setEditingItem(null);
    setData([]);
    setAllStudents([]);
    setSelectedCourseStudents([]);
    setShowStudentsModal(false);
  };

  // Load data from API
  const load = async (endpoint) => {
    if (!endpoint) return;
    setLoading(true);
    try {
      const res = await axios.get(`${API}/${endpoint}`);
      let fetched = res.data;

      // Normalize students array to numbers (fixes type issues)
      if (endpoint.includes('courses')) {
        fetched = fetched.map(course => ({
          ...course,
          students: course.students ? course.students.map(Number) : []
        }));
      }

      setData(fetched);
    } catch (err) {
      console.error(err);
      setData([]);
    } finally {
      setLoading(false);
    }
  };

  // Navigate to page and load data
  const goTo = async (newPage) => {
    setPage(newPage);
    setShowForm(false);
    setEditingItem(null);
    setFormData({});
    setShowStudentsModal(false);

    const endpoint = getEndpoint(newPage);
    if (endpoint) await load(endpoint);
  };

  // Auto-navigate after login
  useEffect(() => {
    if (user && page === 'dashboard') {
      goTo('courses');
    }
    if (user?.role === 'instructor') {
      load('users?role=student').then(res => setAllStudents(res || []));
    }
  }, [user]);

  // Enroll in course
  const enroll = async (courseId) => {
    try {
      const res = await axios.post(`${API}/courses/${courseId}/enroll`, { studentid: user.id });
      setData(prev => prev.map(c =>
        c.id === res.data.id ? { ...c, students: res.data.students ? res.data.students.map(Number) : [] } : c
      ));
      alert('Enrolled successfully!');
    } catch (err) {
      alert('Already enrolled or error occurred');
    }
  };

  // Drop course
  const drop = async (courseId) => {
    try {
      const res = await axios.post(`${API}/courses/${courseId}/drop`, { studentid: user.id });
      setData(prev => prev.map(c =>
        c.id === res.data.id ? { ...c, students: res.data.students ? res.data.students.map(Number) : [] } : c
      ));
      alert('Dropped successfully!');
    } catch (err) {
      alert('Error dropping course');
    }
  };

  // CRUD: Start add
  const startAdd = () => {
    setEditingItem(null);
    setFormData(getEmptyForm(page));
    setShowForm(true);
  };

  // CRUD: Start edit
  const startEdit = (item) => {
    setEditingItem(item);
    setFormData({ ...item });
    setShowForm(true);
  };

  // CRUD: Save (create or update)
  const saveItem = async (e) => {
    e.preventDefault();
    let base = page === 'students' ? 'users' : page;
    let payload = { ...formData };

    if (page === 'courses') payload.instructorid = user.id;
    if (page === 'students') payload.role = 'student';
    if ((page === 'assignments' || page === 'announcements') && !payload.courseid) {
      payload.courseid = prompt('Enter Course ID:') || 1;
    }

    try {
      if (editingItem) {
        await axios.put(`${API}/${base}/${editingItem.id}`, payload);
        alert('Updated!');
      } else {
        await axios.post(`${API}/${base}`, payload);
        alert('Created!');
      }
      setShowForm(false);
      await goTo(page);
    } catch (err) {
      alert('Error: ' + (err.response?.data?.error || 'Check fields'));
    }
  };

  // CRUD: Delete
  const deleteItem = async (id) => {
    if (!confirm('Delete permanently?')) return;
    const base = page === 'students' ? 'users' : page;
    try {
      await axios.delete(`${API}/${base}/${id}`);
      alert('Deleted');
      await goTo(page);
    } catch (err) {
      alert('Delete failed');
    }
  };

  // View enrolled students (instructor only)
  const viewEnrolledStudents = async (course) => {
    try {
      const res = await axios.get(`${API}/users`);
      const students = res.data.filter(u => u.role === 'student' && course.students.includes(u.id));
      setSelectedCourseStudents(students);
      setShowStudentsModal(true);
    } catch (err) {
      alert('Failed to load students');
    }
  };

  return (
    <div className="app">
      {/* Login Page */}
      {page === 'login' && !user && (
        <div className="container">
          <h1>NM Student Portal</h1>
          <form onSubmit={login}>
            <input
              type="email"
              placeholder="Enter your email"
              value={emailInput}
              onChange={(e) => setEmailInput(e.target.value)}
              required
              style={{ width: '100%', padding: '10px', margin: '10px 0' }}
            />
            <button type="submit" className="btn">Login</button>
          </form>
        </div>
      )}

      {/* Dashboard (after login) */}
      {user && (
        <>
          <nav>
            <button onClick={() => goTo('courses')} className="btn">Courses</button>
            {user.role === 'student' && (
              <>
                <button onClick={() => goTo('assignments')} className="btn">Assignments</button>
                <button onClick={() => goTo('submissions')} className="btn">My Submissions</button>
              </>
            )}
            {user.role === 'instructor' && (
              <>
                <button onClick={() => goTo('assignments')} className="btn">Assignments</button>
                <button onClick={() => goTo('announcements')} className="btn">Announcements</button>
                <button onClick={() => goTo('students')} className="btn">Students</button>
              </>
            )}
            <button onClick={logout} className="btn" style={{ background: '#e74c3c' }}>Logout</button>
          </nav>

          <div className="container">
            <h1>Welcome, {user.name} ({user.role})</h1>
            <h2>{page.charAt(0).toUpperCase() + page.slice(1)}</h2>

            {user.role === 'instructor' && ['courses', 'assignments', 'announcements', 'students'].includes(page) && (
              <button onClick={startAdd} className="btn">+ Add New</button>
            )}

            {loading && <p>Loading...</p>}

            {/* Table */}
            {data.length > 0 && (
              <table>
                <thead>
                  <tr>
                    <th>ID</th>
                    {page === 'courses' && <th>Title</th>}
                    {page === 'courses' && <th>Description</th>}
                    {page === 'courses' && <th>Syllabus</th>}
                    {page === 'courses' && user.role === 'instructor' && <th>Enrolled</th>}
                    {page === 'courses' && user.role === 'student' && <th>Action</th>}

                    {page === 'assignments' && <th>Title</th>}
                    {page === 'assignments' && <th>Due Date</th>}
                    {page === 'assignments' && <th>Description</th>}

                    {page === 'submissions' && <th>Assignment ID</th>}
                    {page === 'submissions' && <th>Grade</th>}
                    {page === 'submissions' && <th>File</th>}

                    {page === 'announcements' && <th>Title</th>}
                    {page === 'announcements' && <th>Message</th>}

                    {page === 'students' && <th>Name</th>}
                    {page === 'students' && <th>Email</th>}

                    {(user.role === 'instructor' && ['courses', 'assignments', 'announcements', 'students'].includes(page)) && <th>Actions</th>}
                    {page === 'submissions' && user.role === 'instructor' && <th>Grade</th>}
                  </tr>
                </thead>
                <tbody>
                  {data.map(item => (
                    <tr key={item.id}>
                      <td>{item.id}</td>

                      {page === 'courses' && <td>{item.title}</td>}
                      {page === 'courses' && <td>{item.description}</td>}
                      {page === 'courses' && <td>{item.syllabus || '—'}</td>}
                      {page === 'courses' && user.role === 'instructor' && (
                        <td>
                          <button onClick={() => viewEnrolledStudents(item)} className="btn">
                            View ({item.students?.length || 0})
                          </button>
                        </td>
                      )}
                      {page === 'courses' && user.role === 'student' && (
                        <td>
                          <button
                            onClick={() => item.students.includes(user.id) ? drop(item.id) : enroll(item.id)}
                            className="btn"
                            style={{ background: item.students.includes(user.id) ? '#e67e22' : '#4facfe' }}
                          >
                            {item.students.includes(user.id) ? 'Drop' : 'Enroll'}
                          </button>
                        </td>
                      )}

                      {page === 'assignments' && <td>{item.title}</td>}
                      {page === 'assignments' && <td>{item.duedate || 'No due date'}</td>}
                      {page === 'assignments' && <td>{item.description}</td>}
                      {page === 'assignments' && user.role === 'instructor' && (
                        <td>
                          <button onClick={() => startEdit(item)} className="btn">Edit</button>
                          <button onClick={() => deleteItem(item.id)} className="btn" style={{ background: '#e74c3c' }}>Delete</button>
                        </td>
                      )}

                      {page === 'submissions' && <td>{item.assignmentid}</td>}
                      {page === 'submissions' && <td>{item.grade !== null ? `${item.grade}/100` : 'Not graded'}</td>}
                      {page === 'submissions' && <td>{item.fileurl ? <a href={item.fileurl} target="_blank" rel="noreferrer">View</a> : '—'}</td>}
                      {page === 'submissions' && user.role === 'instructor' && (
                        <td>
                          <button onClick={() => {
                            const grade = prompt('Enter grade (0-100):');
                            if (grade !== null && !isNaN(grade)) {
                              const feedback = prompt('Enter feedback (optional):') || '';
                              axios.put(`${API}/submissions/${item.id}/grade`, { grade: parseInt(grade), feedback })
                                .then(() => { alert('Graded!'); goTo('submissions'); })
                                .catch(() => alert('Grading failed'));
                            }
                          }} className="btn">Grade</button>
                        </td>
                      )}

                      {page === 'announcements' && <td>{item.title}</td>}
                      {page === 'announcements' && <td>{item.message}</td>}
                      {page === 'announcements' && user.role === 'instructor' && (
                        <td>
                          <button onClick={() => startEdit(item)} className="btn">Edit</button>
                          <button onClick={() => deleteItem(item.id)} className="btn" style={{ background: '#e74c3c' }}>Delete</button>
                        </td>
                      )}

                      {page === 'students' && <td>{item.name}</td>}
                      {page === 'students' && <td>{item.email}</td>}
                      {page === 'students' && (
                        <td>
                          <button onClick={() => startEdit(item)} className="btn">Edit</button>
                          <button onClick={() => deleteItem(item.id)} className="btn" style={{ background: '#e74c3c' }}>Delete</button>
                        </td>
                      )}
                    </tr>
                  ))}
                </tbody>
              </table>
            )}

            {/* Form Modal */}
            {showForm && (
              <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <div style={{ background: 'white', color: '#333', padding: '30px', borderRadius: '10px', width: '400px' }}>
                  <h3>{editingItem ? 'Edit' : 'Add'} {page.slice(0, -1)}</h3>
                  <form onSubmit={saveItem}>
                    {Object.keys(getEmptyForm(page)).map(key => (
                      <input
                        key={key}
                        type="text"
                        placeholder={key.charAt(0).toUpperCase() + key.slice(1)}
                        value={formData[key] || ''}
                        onChange={(e) => setFormData({ ...formData, [key]: e.target.value })}
                        style={{ width: '100%', padding: '10px', margin: '10px 0' }}
                        required
                      />
                    ))}
                    <button type="submit" className="btn">Save</button>
                    <button type="button" onClick={() => setShowForm(false)} className="btn" style={{ background: '#e74c3c', marginLeft: '10px' }}>Cancel</button>
                  </form>
                </div>
              </div>
            )}

            {/* Students Modal */}
            {showStudentsModal && (
              <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <div style={{ background: 'white', color: '#333', padding: '30px', borderRadius: '10px', maxWidth: '500px' }}>
                  <h3>Enrolled Students</h3>
                  {selectedCourseStudents.length > 0 ? (
                    <ul>
                      {selectedCourseStudents.map(s => (
                        <li key={s.id}>{s.name} - {s.email}</li>
                      ))}
                    </ul>
                  ) : <p>No students enrolled.</p>}
                  <button onClick={() => setShowStudentsModal(false)} className="btn">Close</button>
                </div>
              </div>
            )}
          </div>
        </>
      )}

      <footer>
        <h3>NM Student Portal © 2025</h3>
        <p>Full Role-Based System • All Features Working</p>
      </footer>
    </div>
  );
}

export default App;
